"""Build the static, public course website from curated content and assets."""
from pathlib import Path
import json, html, re, subprocess, textwrap
from pypdf import PdfReader
from reportlab.pdfgen import canvas
from reportlab.lib.colors import HexColor
from reportlab.lib.utils import simpleSplit

SITE=Path(__file__).resolve().parents[1]
DIST=SITE/"dist/client"
DATA=json.loads((SITE/"content/course.json").read_text())
SESSIONS=DATA["sessions"]
CAREER=json.loads((SITE/"content/career-resources.json").read_text())
e=html.escape

def write(path,text):
 p=DIST/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)

def rail(session=0):
 active=''.join(f'<li><a class="{ "active" if session==s["id"] else ""}" href="/sessions/{s["id"]:02}/"><span class="number">{s["id"]:02}</span><span>{e(s["topic"])}</span></a></li>' for s in SESSIONS)
 future=''.join(f'<li><div class="locked" aria-disabled="true"><span class="number">{n:02}</span><span>{e(t)}<small>NOT YET RELEASED</small></span></div></li>' for n,t in DATA["future"])
 return f'<aside class="course-rail" aria-label="Course journey"><div class="rail-title">Your course journey · 5 of 14 covered</div><ol class="rail-list">{active}{future}</ol><div class="rail-note">Excel and SPSS are the core tools. Python and R are optional extensions.<br><br>Practice XP has no effect on your course grade.</div></aside>'

def page(title,content,active="Home",session=0):
 nav=[("Home","/"),("Sessions","/sessions/"),("Practice Lab","/practice/"),("Study Tutor","/tutor/"),("Reference Library","/reference/"),("Career Toolkit","/career/"),("About","/about/")]
 links=''.join(f'<a href="{url}"{ " aria-current=page" if label==active else ""}>{label}</a>' for label,url in nav)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | GC1015 Learning Studio</title><meta name="description" content="Explore quantitative methods through interactive experiments, study toolkits, laboratory guides, slides, mind maps, and audio. Sessions 01–05 are released."><meta name="theme-color" content="#57068c"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/studio.css"><link rel="stylesheet" href="/assets/language.css"><script src="/assets/course-data.js" defer></script><script src="/assets/studio.js" defer></script><script src="/assets/i18n.js" defer></script><script src="/assets/tutor.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><div class="top-inner"><a class="brand" href="/"><span class="monogram">Q.</span><span><strong>GC1015 Learning Studio</strong><small>NYU SPS · Professor Ken Ezekwem</small></span></a><button class="menu-button" aria-expanded="false" aria-controls="main-nav">Menu</button><nav class="main-nav" id="main-nav" aria-label="Main navigation">{links}</nav><label class="language-picker"><span>Language</span><select id="site-language" aria-label="Study language"><option value="en">English</option><option value="zh">中文（普通话）</option><option value="es">Español</option><option value="hi">हिन्दी</option></select></label></div></header><div class="shell">{rail(session)}<main class="page" id="main">{content}</main></div><footer class="footer"><div class="footer-inner"><div>Quantitative Methods for Business Analysis · Fall 2026<br>Original course resources and optional practice. Released through Session 05.</div><div><a href="/about/">About Professor Ken</a><a href="/reference/">Sources & reference</a><a href="/practice/#passport">Your device passport</a><br>Progress stays in this browser. No login, leaderboard, or course-grade connection.</div></div></footer><div class="translation-status" id="translation-status" role="status" hidden></div></body></html>'''

def cards():
 return '<div class="session-grid">'+''.join(f'<a class="session-card" href="/sessions/{s["id"]:02}/"><span class="num">SESSION {s["id"]:02} · {s["module"]}</span><h3>{e(s["title"])}</h3><p>{e(s["summary"])}</p><span class="arrow">Study, explore & practice →</span></a>' for s in SESSIONS)+'</div>'

def locked():
 return '<div class="closed-grid">'+''.join(f'<div class="closed-card" aria-disabled="true"><small>SESSION {n:02}</small><strong>{e(t)}</strong><span>Locked · opens after it is covered and released</span></div>' for n,t in DATA["future"])+'</div>'

def passport():
 return '<aside class="passport" aria-label="Evidence passport"><p class="eyebrow">Your evidence passport</p><strong class="score"><span data-xp>0</span> <small>XP</small></strong><div class="badge-line"><span data-stamps>0</span> / 5 evidence stamps</div><progress data-progress max="350" value="0" aria-label="Practice progress"></progress><p class="small">Earn progress by exploring and explaining.</p><a href="/practice/#passport">View your stamps →</a></aside>'

def experiment(default=3):
 return f'<section class="lab-frame" aria-label="Interactive practice" data-default-session="{default}"><div class="lab-top"><div><strong>THE EVIDENCE LAB</strong><p>Predict → change one input → explain what happened</p></div><span class="pill teal">Optional · ungraded</span></div><div class="experiment-tabs" role="tablist" aria-label="Choose an experiment">'+''.join(f'<button role="tab" id="tab-{s["id"]}" aria-controls="experiment-panel" data-experiment="{s["id"]}" aria-selected="false">{s["id"]:02} · {["Question","Measures","Distribution","Risk","Uncertainty"][s["id"]-1]}</button>' for s in SESSIONS)+'</div><div class="experiment" id="experiment-panel" role="tabpanel"></div></section>'

home=f'''<div class="welcome"><div><p class="eyebrow">Quantitative Methods for Business Analysis</p><h1>Make the evidence move.</h1><p class="lead">A learning studio for better questions, clearer charts, and decisions you can explain. Start with a small experiment. See what changes.</p><div class="action-row"><a class="button" href="/sessions/05/">Continue with Session 05 →</a><a class="button secondary" href="/practice/">Explore the practice lab</a></div></div>{passport()}</div>{experiment()}<div class="section-heading"><div><p class="eyebrow">Covered & ready to explore</p><h2>Your learning journey</h2></div><a href="/sessions/">See the full course map →</a></div>{cards()}<div class="section-heading"><h2>A reference that travels with you</h2></div><section class="reference-feature"><div><p class="eyebrow">Independent reference library</p><h2>The Measurement Atlas</h2><p>Connect measurement levels to statistical methods, visual choices, and business examples. Explore this reference across sessions, including optional topics beyond current coverage.</p><a class="button" href="/reference/">Open the atlas →</a></div><div class="measure-grid"><div><b>Nominal</b><small>Category, without order</small></div><div><b>Ordinal</b><small>Ordered, unequal gaps</small></div><div><b>Interval</b><small>Equal gaps, arbitrary zero</small></div><div><b>Ratio</b><small>Equal gaps, meaningful zero</small></div></div></section><div class="section-heading"><h2>Coming later</h2></div><p class="muted">These sessions remain visible on the map. Their lessons and files are not released here yet.</p>{locked()}'''
write("index.html",page("Home",home))
write("sessions/index.html",page("Course journey",'<div class="intro"><p class="eyebrow">The course map</p><h1>Build understanding,<br>one decision at a time.</h1><p class="lead">Sessions 01–05 are open. Each session brings together its study guide, lab, visual references, slides, and audio.</p></div>'+cards()+'<div class="section-heading"><h2>Upcoming sessions</h2></div>'+locked(),"Sessions"))
practice='<div class="welcome"><div><p class="eyebrow">Interactive practice</p><h1>Predict. Explore.<br>Explain.</h1><p class="lead">Try five experiments with fictional data. Change the assumptions, inspect the result, and test your reasoning. These activities are optional and ungraded.</p></div>'+passport()+'</div>'+experiment()+'<section id="quiz-area" aria-label="Knowledge checks"></section><section id="passport" class="challenge"><p class="eyebrow">Evidence passport</p><h2>Collect understanding, not just clicks.</h2><p class="small">Each correct knowledge check earns 10 XP once. Explore its experiment and answer all three checks to earn a 40 XP evidence stamp. Maximum: 350 XP. Progress stays on this device and does not affect your course grade.</p><div class="badge-grid" id="badge-grid"></div><details style="margin-top:22px"><summary>Manage my device progress</summary><p class="small">Resetting removes only this browser’s practice answers and stamps. There is no cloud account to recover them from.</p><button class="secondary" id="reset-request">Start a progress reset</button><div id="reset-confirm" hidden><p>Confirm the reset of this device’s practice passport.</p><button class="primary" id="reset-confirm-button">Reset my practice progress</button> <button class="secondary" id="reset-cancel">Keep my progress</button></div></details></section>'
write("practice/index.html",page("Practice lab",practice,"Practice Lab"))

for s in SESSIONS:
 i=s["id"];asset=f"/assets/s{i:02}";pdf=PdfReader(DIST/asset[1:]/"slides.pdf");slide_count=len(pdf.pages)
 concept='<div class="concept-grid">'+''.join(f'<article class="concept"><h3>{e(n[0])}</h3><strong>{e(n[1])}</strong><p>{e(n[2])}</p><details><summary>Connect it to a business example</summary><p>{e(n[3])}</p></details></article>' for n in s["nodes"])+'</div>'
 objectives='<ul class="objective-list">'+''.join(f'<li>{e(o)}</li>' for o in s["outcomes"])+'</ul>'
 labid={1:"Session 01",2:"S02P",3:"LAB01",4:"LAB02",5:"S05P"}[i]
 labextras=f'<li><a href="{asset}/{e(labid)}_Learning_Workbook.xlsx">Excel learning workbook</a></li><li><a href="{asset}/{e(labid)}_SPSS.sps">SPSS syntax</a></li>'
 if i==1:labextras=f'<li><a href="{asset}/Session%2001%20-%20Analysis%20Practice%20Workbook.xlsx">Excel practice workbook</a></li><li><a href="{asset}/Session%2001%20-%20SPSS%20Practice%20Syntax.sps">SPSS practice syntax</a></li><li><a href="{asset}/learning-companion.pdf">Printable learning companion · PDF</a></li>'
 else:
  if (DIST/asset[1:]/"spss-guide.pdf").exists():labextras+=f'<li><a href="{asset}/spss-guide.pdf">SPSS VCL guide · PDF</a></li>'
  labextras+=f'<li><a href="{asset}/student-package.zip">Complete student lab package · ZIP</a></li>'
 labextras+=''.join(f'<li><a href="{asset}/{e(f.name)}">{e(f.name)} · data</a></li>' for f in (DIST/asset[1:]).glob("*.csv"))
 note=''
 if i==4:note='<div class="notice"><strong>Updated study edition.</strong> This session uses the corrected 98-slide deck and corrected toolkit. Some references in the original lab package use the earlier slide numbering. Find the matching topic by title when the number differs. Assignment directions remain in Brightspace.</div>'
 infographic=f'<a href="{asset}/infographics.pdf">Full infographic atlas · PDF</a>' if i>=3 else (f'<a href="{asset}/infographic.png">View the infographic · image</a>' if i==2 else f'<a href="{asset}/mind-map-01.svg">View the decision-to-evidence overview</a>')
 audio=f'<audio controls preload="none" src="{asset}/primer.mp3" aria-label="Session {i:02} audio primer">Your browser does not support audio. <a href="{asset}/primer.mp3">Download the primer</a>.</audio>'
 body=f'''<div class="intro"><span class="pill">Covered · Session {i:02}</span><span class="pill teal">{s["module"]}</span><p class="eyebrow">{e(s["topic"])}</p><h1>{e(s["title"])}</h1><p class="lead">{e(s["summary"])}</p><a class="button" href="/practice/?session={i}">Try this session’s experiment →</a></div><nav class="session-tabs" aria-label="Session resources"><a href="#study">Study toolkit</a><a href="#laboratory">Laboratory</a><a href="#mind-map">Mind map</a><a href="#infographics">Infographics</a><a href="#listen">Listen</a><a href="#slides">Full slides</a></nav>{note}{f'<p><a href="{asset}/blog.html">Read the session introduction →</a></p>' if i>1 else ''}<h2>What you can explain</h2>{objectives}{concept}<section id="study"><div class="section-heading"><h2>The study toolkit</h2></div><div class="resource-grid"><article class="resource"><span class="kind">Start here · concise edition</span><h3>A focused route through the essentials</h3><p>Central ideas, worked examples, misconceptions, and study checks in a readable card layout.</p><div class="action-row"><a class="button" href="{asset}/toolkit-concise.html">Read the concise toolkit</a><a href="{asset}/toolkit-concise.pdf">Download PDF</a></div></article><article class="resource"><span class="kind">Go deeper · full edition</span><h3>The complete explanations</h3><p>Keep every section close at hand, including software routes, worked reasoning, glossary, and references.</p><div class="action-row"><a class="button secondary" href="{asset}/toolkit.html">Read the full toolkit</a><a href="{asset}/toolkit.pdf">Download PDF</a></div></article></div></section><section id="laboratory"><div class="section-heading"><h2>From concept to evidence</h2></div><article class="resource"><span class="kind">{"Ungraded guided demonstration" if i==1 else labid+" · student laboratory"}</span><h3>Excel and SPSS, with the reasoning visible</h3><p>The student guide keeps the task, steps, checks, and evidence requirements together. Use Brightspace for the current assignment directions and submission.</p><a class="button" href="{asset}/lab.html">Open the laboratory guide →</a>{f' <a href="{asset}/lab.pdf">Guide PDF</a>' if i>1 else ''}<ul>{labextras}</ul><p class="small">Python and R extensions inside the student package are optional. The website's practice challenges are separate from assessed work.</p></article></section><section id="mind-map"><div class="section-heading"><h2>See the connections</h2><a href="{asset}/mind-map.pdf">Multi-page mind map · PDF →</a></div>{f'<p><a href="{asset}/mind-map-original.html">Open the original interactive mind map →</a></p>' if i==5 else ''}<p class="muted">Expand a branch, follow the relationship, then explain it in your own words.</p>{concept}</section><section id="infographics"><div class="section-heading"><h2>Visual reference</h2></div><article class="resource">{infographic}<p class="small">Open the full visual, then use the text version to review its reasoning.</p>{f'<a href="{asset}/infographics-reading.html">Accessible reading version →</a>' if i>=2 else '<p>Decision → evidence → tool check → interpretation → next action.</p>'}</article><div class="gallery" data-gallery="{i}"></div></section><section id="listen"><div class="section-heading"><h2>Listen, then retrieve</h2></div><article class="resource"><span class="kind">Audio primer</span><h3>Bring the session back into focus</h3>{audio}<a href="{asset}/primer-transcript.txt">Read the primer transcript</a> · <a href="{asset}/primer.mp3">Download audio</a><p class="small">After listening, name the main decision and one limitation without looking at your notes.</p></article></section><section id="slides"><div class="section-heading"><h2>The full student slide deck</h2><a href="{asset}/slides.pdf">Open {slide_count}-page PDF →</a></div><article class="resource"><p>The complete student deck is available for this covered session. Open it separately or load it below.</p><button class="secondary" data-load-pdf="{asset}/slides.pdf" data-pdf-title="Session {i:02} full student slides">Load the slide viewer</button><div class="pdf-slot"></div></article></section>'''
 write(f"sessions/{i:02}/index.html",page(f"Session {i:02}",body,"Sessions",i))

reference='''<div class="intro"><p class="eyebrow">Independent reference library</p><h1>Find the method.<br>Choose the visual.</h1><p class="lead">The Measurement Atlas connects measurement levels, subtypes, statistical methods, and chart choices. It belongs here as a reference across sessions.</p><span class="pill teal">Optional reference · includes topics beyond Session 05</span><div class="action-row"><a class="button" href="/reference/measurement-atlas/">Open the atlas full screen →</a><a class="button secondary" href="/reference/measurement-atlas/measurement-atlas.pdf">Download the complete atlas PDF</a></div></div><iframe class="atlas-frame" src="/reference/measurement-atlas/" title="GC1015 Measurement Atlas" loading="lazy"></iframe><div class="section-heading"><h2>Build on authoritative sources</h2></div><div class="resource-grid"><article class="resource"><h3>Statistical foundations</h3><p>Definitions, assumptions, study design, and exploratory analysis.</p><ul><li><a href="https://www.openintro.org/book/os/">OpenIntro Statistics</a></li><li><a href="https://online.stat.psu.edu/stat200/">Penn State STAT 200</a></li><li><a href="https://www.itl.nist.gov/div898/handbook/">NIST Engineering Statistics Handbook</a></li></ul></article><article class="resource"><h3>Course connections</h3><p>Each session's full toolkit carries its own references. The atlas adds combinations of measurement levels, method assumptions, and visualization cautions.</p><a href="/sessions/">Return to the session toolkits →</a><p class="small">Original teaching synthesis. External sources retain their own licenses and authorship.</p></article></div>'''
write("reference/index.html",page("Measurement reference library",reference,"Reference Library"))
maps_community='''<section class="maps-community" id="maps" aria-labelledby="maps-title"><p class="eyebrow">Optional · Your student community</p><h2 id="maps-title">Meet your MAPS community.</h2><p>Connect with fellow students through the Management &amp; Analytics Professionals Society. Explore networking, alumni conversations, professional learning, and ways to contribute.</p><div class="action-row"><a class="button" href="https://engage.nyu.edu/organization/MAPS" target="_blank" rel="noopener">Explore &amp; join MAPS ↗</a><a href="mailto:sps.maps@nyu.edu?subject=Interested%20in%20joining%20MAPS">Contact the MAPS team</a></div><p class="small">Sign in to NYU Engage with your NYU account to see available membership options. If joining is unavailable, email <a href="mailto:sps.maps@nyu.edu">sps.maps@nyu.edu</a> to ask how to get involved.</p><details><summary>Events &amp; ways to stay connected</summary><p>No upcoming public events were listed on the official MAPS Engage page when checked on October 3, 2026. New announcements and RSVP information are available through Engage.</p><div class="action-row"><a href="https://engage.nyu.edu/organization/maps/events" target="_blank" rel="noopener">Latest MAPS events ↗</a><a href="https://www.instagram.com/nyu_maps/" target="_blank" rel="noopener">MAPS on Instagram ↗</a><a href="https://www.linkedin.com/company/nyu-sps-management-analytics-student-association/" target="_blank" rel="noopener">MAPS on LinkedIn ↗</a><a href="https://www.facebook.com/groups/nyumssa" target="_blank" rel="noopener">MAPS Facebook group ↗</a></div><p class="small">Membership and contact information: <a href="https://engage.nyu.edu/organization/MAPS" target="_blank" rel="noopener">official NYU Engage listing</a>.</p></details></section>'''
career_intro='''<div class="intro"><p class="eyebrow">Section 10 · Bridge, Stretch & Career Toolkit</p><h1>Keep learning.<br>Make it your own.</h1><p class="lead">Recommended, optional resources to strengthen course skills and build evidence for your career. Complete them during or after the course, at your own pace.</p><div class="notice"><strong>Free LinkedIn Learning with your NYU email.</strong> Sign in through NYU's LinkedIn Learning access to take these courses at no cost. Individual courses offer completion certificates. The Wolfram Research professional certificate requires the full learning path and final exam.<br><br>These resources are not required or graded and do not affect your course grade. Choose what serves your interests. You do not need to complete every option.</div><p class="small"><a href="#maps">Meet your MAPS community ↓</a></p></div>'''
cats=list(dict.fromkeys(x["category"] for x in CAREER))
filters='<div class="resource-filter" aria-label="Filter career resources"><button data-filter="All" aria-pressed="true">All · 15 resources</button>'+''.join(f'<button data-filter="{e(c)}" aria-pressed="false">{e(c)}</button>' for c in cats)+'</div>'
links=''
for x in CAREER:
 category=x["category"]
 desc={"LinkedIn Learning":"Deepen your course skills and earn a completion credential.","Excel":"Support for the core spreadsheet workflow.","SPSS":"Documentation and guided support for the core statistics workflow.","Python":"Optional language and data-analysis extension.","R":"Optional statistics and data-analysis extension.","Google Colab & Jupyter Notebooks":"Run and inspect notebooks in an accessible learning environment.","Statistical Foundations & Data Communication":"Strengthen statistical reasoning and communication."}[category]
 title=re.sub(r"^(?:LinkedIn Learning - |\d+ - )","",x["title"])
 links+=f'<a class="link-card" href="{e(x["url"])}" target="_blank" rel="noopener" data-category="{e(category)}" data-search="{e(title.lower())}"><small>{e(category)}</small><h3>{e(title)}</h3><p>{desc}</p><span>Open resource ↗</span></a>'
write("career/index.html",page("Optional career toolkit",career_intro+'<label for="resource-search" class="small">Find a course, tool, or topic</label><br><input class="search-input" id="resource-search" type="search" placeholder="Try Excel, statistics, Python…">'+filters+'<p id="resource-count" class="small" aria-live="polite">15 resources</p><div class="resource-grid" id="career-grid">'+links+'</div><div class="section-heading"><h2>Turn learning into evidence</h2></div><div class="concept-grid"><article class="concept"><h3>Build a small portfolio artifact</h3><p>Use public or fictional data. State the business question, document data quality, choose an appropriate chart, and explain the result and its limits.</p></article><article class="concept"><h3>Explain the work</h3><p>A certificate records completion. A clear, reproducible analysis shows what you can do. Add a short reflection on the choices you made and what you would investigate next.</p></article></div>'+maps_community,"Career Toolkit"))
about='''<div class="about-grid"><div><p class="eyebrow">Meet your professor</p><h1>Kenechukwu<br>“Ken” Ezekwem, PhD</h1><span class="pill">Clinical Assistant Professor</span><span class="pill teal">Management & Analytics · NYU SPS</span><p class="lead">Better analysis starts with a better question.</p><p>Professor Ken teaches at the intersection of analytics, AI, and business operations. His courses connect quantitative reasoning with practical decisions, inspectable evidence, and responsible use of technology.</p><p>He emphasizes hands-on learning: define the problem, examine the data, choose a defensible method, check the result, and explain what it supports. A chart or a statistical output is a starting point for judgment.</p><p>He is also Faculty Advisor to the Management & Analytics Professionals Society (<a href="/career/#maps">MAPS</a>). This Learning Studio extends his classroom with small experiments, worked explanations, and resources students can revisit.</p><div class="action-row"><a class="button" href="https://www.sps.nyu.edu/faculty-directory/21052-kenechukwu-c-ezekwem.html" target="_blank" rel="noopener">Official NYU faculty profile ↗</a><a href="mailto:kce232@nyu.edu">Contact Professor Ken</a></div><p class="small" style="margin-top:18px">Biography based on the <a href="https://www.sps.nyu.edu/faculty-directory/21052-kenechukwu-c-ezekwem.html">NYU SPS faculty directory</a>. Photograph supplied by Professor Ken.</p></div><figure><img class="photo" src="/assets/professor-ken.png" alt="Professor Kenechukwu Ezekwem, PhD, Faculty Advisor for MAPS" width="1121" height="1403"><figcaption>Professor Ken Ezekwem</figcaption></figure></div><div class="section-heading"><h2>How we learn here</h2></div><div class="concept-grid"><article class="concept"><h3>Start with a decision</h3><p>Name the stakeholder and the choice before selecting a statistical procedure.</p></article><article class="concept"><h3>Make the reasoning visible</h3><p>Show counts, denominators, units, assumptions, and limits so the work can be inspected.</p></article><article class="concept"><h3>Learn through experiments</h3><p>Predict the result, change an input, compare the evidence, and explain the difference.</p></article><article class="concept"><h3>Keep extending</h3><p>Use the optional toolkit during or after the course. Build confidence at your own pace.</p></article></div>'''
write("about/index.html",page("About Professor Ken",about,"About"))
write("assets/favicon.svg",'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#57068c"/><text x="12" y="45" font-family="Georgia,serif" font-size="44" fill="white">Q</text></svg>')
write("assets/course-data.js","window.COURSE_DATA="+json.dumps(DATA,ensure_ascii=False)+";")


tutor='''<div class="intro"><p class="eyebrow">Your revision companion</p><h1>Talk it through.<br>Keep the thinking yours.</h1><p class="lead">Ask a general question about the whole course, revisit a concept, or find the right slide, toolkit section, or lab guide.</p><span class="pill teal">Concept revision · Sessions 01–04</span><span class="pill">Whole-course navigation</span></div><div class="tutor-layout"><section class="chat-card" aria-label="AI study conversation"><div class="chat-heading"><div><strong>GC1015 Study Tutor</strong><p class="small">AI learning support · Professor Ken’s course sources</p></div><span class="pill teal">Hints, not completed work</span></div><div class="chat-thread" id="chat-thread" aria-live="polite" aria-relevant="additions"><div class="chat-welcome"><h2>A good question is a good start.</h2><p>Choose a starting point below, or tell the tutor where your reasoning gets stuck.</p></div></div><div class="starter-prompts"><button class="starter" data-prompt="Why do the mean and median respond differently to a long tail?">Mean or median?</button><button class="starter" data-prompt="Help me understand why P(A given B) differs from P(B given A).">Conditional probability</button><button class="starter" data-prompt="How can I get started on a lab without having you complete it?">Plan my next step</button><button class="starter" data-prompt="Where can I find the Session 05 slides and optional Excel support?">Find a resource</button></div><form id="chat-form"><label for="chat-message">What would you like to understand?</label><textarea id="chat-message" rows="3" maxlength="1600" required placeholder="Describe the concept, or share the step you already tried…"></textarea><div class="chat-actions"><button class="button" id="send-question" type="submit">Ask the study tutor →</button><button class="secondary" id="clear-chat" type="button">New conversation</button></div><p class="small" id="chat-status" role="status"></p></form></section><aside class="tutor-guide"><article class="resource"><span class="kind">A deliberate learning boundary</span><h3>One class back, for revision</h3><p>Session 05 is covered. Detailed revision currently goes through Session 04. After another session is covered and released, the revision boundary can advance.</p><p>The tutor can still explain the whole course map and help locate Session 05 resources.</p></article><article class="resource"><span class="kind">Keep your own work</span><h3>Help without handing over the thinking</h3><p>Get a hint, a concept explanation, a different fictional example, or a source to inspect. The tutor does not complete assignments, worksheets, quizzes, code tasks, or submissions, even when they are ungraded.</p></article><article class="resource"><span class="kind">Study in your language</span><h3>Read. Ask. Listen.</h3><p>Use the language menu for English, Simplified Chinese (Mandarin), Spanish, or Hindi. Listen to a tutor reply using its audio button.</p><p class="small">Digital text uses AI translation. Original PDFs, images, and recorded primers remain in English. Check important terminology against the English source. Tutor audio is AI-generated, not Professor Ken’s voice.</p></article><article class="resource"><h3>Conversation privacy</h3><p class="small">Your question and recent messages are sent to the AI service to produce a reply. This site does not save conversations or connect them to course grades. Avoid personal or confidential information. Starting a new conversation clears the messages here.</p><a href="/sessions/">Browse the course sources →</a></article></aside></div>'''
