# Mind maps: an overview plus one page per concept branch, with a real content hierarchy.
for s in SESSIONS[:4]:
 i=s["id"];folder=DIST/f"assets/s{i:02}"
 c=canvas.Canvas(str(folder/"mind-map.pdf"),pagesize=(842,595))
 c.setTitle(f'GC1015 Session {i:02} Multi-page Mind Map')
 def base(number,title):
  c.setFillColor(HexColor("#330662"));c.rect(0,495,842,100,fill=1,stroke=0)
  c.setFillColor(HexColor("#ffffff"));c.setFont("Helvetica-Bold",11);c.drawString(44,563,f'GC1015 · SESSION {i:02} · CONCEPT MAP')
  c.setFont("Helvetica-Bold",25);c.drawString(44,524,title)
  c.setFillColor(HexColor("#645e70"));c.setFont("Helvetica",10);c.drawString(44,25,f'Professor Ken Ezekwem · {s["module"]} · Original learning synthesis')
  c.drawRightString(798,25,f'{number} / 5')
  c.linkURL(f"https://gc1015-learning-studio.kezekwem.chatgpt.site/sessions/{i:02}/",(44,14,650,35),relative=0)
 def box(x,y,w,h,title,body):
  c.setFillColor(HexColor("#f4eef9"));c.setStrokeColor(HexColor("#d9c9e5"));c.roundRect(x,y,w,h,10,fill=1,stroke=1)
  c.setFillColor(HexColor("#57068c"));c.setFont("Helvetica-Bold",14)
  for j,line in enumerate(simpleSplit(title,"Helvetica-Bold",14,w-30)):c.drawString(x+15,y+h-26-j*18,line)
  c.setFillColor(HexColor("#3a3245"));c.setFont("Helvetica",11)
  for j,line in enumerate(simpleSplit(body,"Helvetica",11,w-30)[:5]):c.drawString(x+15,y+h-67-j*16,line)
 base(1,s["title"])
 c.setStrokeColor(HexColor("#ab82c5"));c.setLineWidth(1.6)
 c.line(421,435,226,410);c.line(421,435,616,410);c.line(421,435,421,250);c.line(421,250,226,240);c.line(421,250,616,240)
 c.setFillColor(HexColor("#006d68"));c.roundRect(291,422,260,52,10,fill=1,stroke=0)
 c.setFillColor(HexColor("#ffffff"));c.setFont("Helvetica-Bold",14);c.drawCentredString(421,453,"A decision you can explain")
 c.setFont("Helvetica",10);c.drawCentredString(421,435,"Connect the four branches below")
 for j,n in enumerate(s["nodes"]):
  x=44+(j%2)*390;y=265-(j//2)*170
  box(x,y,364,145,f"{j+1}. {n[0]}",n[2])
 c.showPage()
 for j,n in enumerate(s["nodes"]):
  base(j+2,n[0])
  c.setFillColor(HexColor("#006d68"));c.setFont("Helvetica-Bold",16)
  chain=n[1].replace("→","  >  ").replace("↔","  < >  ").replace("√","sqrt").replace("×","x")
  for k,line in enumerate(simpleSplit(chain,"Helvetica-Bold",16,745)):c.drawString(44,452-k*22,line)
  box(44,230,360,180,"The connection",n[2]);box(438,230,360,180,"A business example",n[3])
  box(44,75,754,125,"Explain it without looking","Name the observational unit, the evidence needed, and one limitation. Connect this branch to the next decision in the session.")
  c.showPage()
 c.save()
 # Text remains selectable in the PDF; browser diagrams use SVG with proper Unicode.
 for j,n in enumerate(s["nodes"]):
  lines=textwrap.wrap(n[2],75)
  svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 470" role="img" aria-label="'+e(n[0])+'"><rect width="900" height="470" rx="15" fill="#f4eef9"/><rect width="900" height="100" rx="15" fill="#330662"/><text x="35" y="40" font-family="sans-serif" font-size="14" fill="white">GC1015 · SESSION '+f'{i:02}'+' · BRANCH '+str(j+1)+'</text><text x="35" y="77" font-family="sans-serif" font-size="27" fill="white">'+e(n[0])+'</text><text x="35" y="150" font-family="sans-serif" font-size="20" fill="#006d68">'+e(n[1])+'</text>'
  svg+=''.join(f'<text x="35" y="{207+k*28}" font-family="sans-serif" font-size="18" fill="#3a3245">{e(line)}</text>' for k,line in enumerate(lines))
  svg+='<text x="35" y="429" font-family="sans-serif" font-size="15" fill="#57068c">Explain the connection. Name the evidence. State a limitation.</text></svg>'
  write(f"assets/s{i:02}/mind-map-{j+1:02}.svg",svg)

